use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let path_str = input.as_str().unwrap();
    let path = path_str.parse::<String>().unwrap();
    let mut result = vec![];
    let mut current_path = String::from("/");
    for c in path.chars() {
        match c {
            '/' => {
                current_path.push('/');
            }
            '.' => {
                if !current_path.is_empty() {
                    result.push(current_path.clone());
                    current_path.clear();
                }
            }
            _ => {
                current_path.push(c);
            }
        }
    }
    if !current_path.is_empty() {
        result.push(current_path.clone());
    }
    Value::Array(result)
}
